import torch, json
sub=torch.load('/work/sub.pt')
targets=['month','plural','roman']
res={}
for L in [24,26,28,29,30,31]:
    D=W(f'model.language_model.layers.{L}.mlp.down_proj.weight')  # d x 12288
    Dn=D/D.norm(dim=0,keepdim=True)
    fr={c:(Q.T@Dn).pow(2).sum(0) for c,Q in sub.items()}
    for t in targets:
        oth=torch.stack([fr[c] for c in fr if c!=t]).max(0).values
        s=fr[t]-1.5*oth
        top=torch.argsort(s,descending=True)
        res[(L,t)]=top[:1024].tolist()
        print(L,t,'top s',[round(x,3) for x in s[top[:5]].tolist()],'s@64',round(s[top[63]].item(),3),'s@256',round(s[top[255]].item(),3))
        for K in [64,128,256,512]:
            json.dump({'kind':'mlp_cluster','layer':L,'indices':top[:K].tolist()},open(f'/work/{t}_L{L}_{K}.json','w'))
# logit lens of top month units at L31
D=W('model.language_model.layers.31.mlp.down_proj.weight')
U=W('lm_head.weight')
for t in targets:
    for u in res[(31,t)][:3]:
        lg=U@D[:,u]; print(t,u,[decode([i]) for i in torch.topk(lg,8).indices.tolist()])

